def transform(grid):
    h, w = len(grid), len(grid[0])
    rows = {r for r in range(h) if grid[r][0] == 1 or grid[r][w - 1] == 1}
    cols = {c for c in range(w) if grid[0][c] == 1 or grid[h - 1][c] == 1}
    line = {(r, c) for r in rows for c in range(w)} | {(r, c) for c in cols for r in range(h)}
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            component = []
            seen.add((r, c))
            while stack:
                rr, cc = stack.pop()
                component.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 2 and (nr,nc) not in seen:
                        seen.add((nr,nc))
                        stack.append((nr,nc))
            if any((rr+dr, cc+dc) in line for rr,cc in component for dr in (-1,0,1) for dc in (-1,0,1)):
                for rr, cc in component:
                    out[rr][cc] = 1
    for rr, cc in line:
        out[rr][cc] = 1
    return out
